const document={querySelector:s=>root.querySelector(s),getElementById:id=>root.getElementById(id),createElement:tag=>globalThis.document.createElement(tag)};

const model=document.querySelector('#model'),viewport=document.querySelector('#viewport'),angle=document.querySelector('#angle'),shell=document.querySelector('#shell');
const W=360,D=214,H=131.25,R=15;
const topY=z=>z<=19?-H/2:z>=45?-H/2+20:-H/2+(z-19)*20/26;
const outline=[];
for(const[cx,cz,start]of[[W/2-R,D/2-R,0],[-W/2+R,D/2-R,90],[-W/2+R,-D/2+R,180],[W/2-R,-D/2+R,270]])for(let j=0;j<=32;j++){const a=(start+j*90/32)*Math.PI/180;outline.push([cx+R*Math.cos(a),cz+R*Math.sin(a)]);}
const boundary=[];
for(let i=0;i<outline.length;i++){const a=outline[i],b=outline[(i+1)%outline.length],cuts=[0];if(Math.abs(a[0]-b[0])<.001&&Math.abs(a[1]-b[1])>4)for(const z of[19,45]){const t=(z-a[1])/(b[1]-a[1]);if(t>0&&t<1)cuts.push(t);}cuts.sort((x,y)=>x-y);for(const t of cuts)boundary.push([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t]);}
for(let i=0;i<boundary.length;i++){const[x,z]=boundary[i],[nx,nz]=boundary[(i+1)%boundary.length],dx=nx-x,dz=nz-z,length=Math.hypot(dx,dz),yaw=Math.atan2(-dz,dx)*180/Math.PI+180;const f=document.createElement('div');f.className='face wall';const shade=Math.round(45+7*Math.sin(yaw*Math.PI/180));f.style.cssText=`width:${length+.5}px;height:${H}px;left:${-(length+.5)/2}px;top:${-H/2}px;transform:translate3d(${(x+nx)/2}px,0,${(z+nz)/2}px) rotateY(${yaw}deg);clip-path:polygon(0 ${topY(nz)+H/2}px,100% ${topY(z)+H/2}px,100% 100%,0 100%);background:linear-gradient(rgb(${shade+8} ${shade+8} ${shade+9}),rgb(${shade} ${shade} ${shade+1}));`;shell.append(f);}
